function pathExercises(name, max){
  max = max || 7;
  const ids = [], avoid = PATH_AVOID[name];
  const ok = id => EXR[id] && !EXR[id].mine && !ids.includes(id) && !(avoid && avoid.test(EXR[id].text + ' ' + EXR[id].title));
  const add = id => { if(ok(id)) ids.push(id); };
  (PATH_PICK[name]||[]).forEach(add);
  (PATH_DEEP[name]||[]).slice(0,3).forEach(add);
  // תרגילים ממוקדים לפי מילים, קודם בשם התרגיל ואחר כך בתוכן
  const keys = PATH_KEYS[name]||[], all = Object.values(EXR).filter(e=>!e.mine);
  let hits = 0;
  keys.forEach(k=>all.forEach(e=>{ if(hits<3 && e.title.includes(k) && ok(e.id)){ ids.push(e.id); hits++; } }));
  keys.forEach(k=>all.forEach(e=>{ if(hits<3 && e.text.includes(k) && ok(e.id)){ ids.push(e.id); hits++; } }));
  // תרגיל מכל מקור שמקושר לפתולוגיה: יסוד, ספירה וכלי
  (PATH_LINKS[name]||[]).forEach(x=>{
    if(EX_EL_NAMES[x]){ add(`el:${x}:guf:0`); add(`el:${x}:regesh:0`); }
    else if(WEEK_SF[x]){ add(`sf:${x}:regesh:0`); add(`sf:${x}:guf:0`); }
    else if(WTOOLS[x]){ add(`${x}:0`); add(`${x}:1`); }
  });
  return ids.slice(0, max);
}

