  const AUD = {"tool-hashkata:26": "src", "tool-hashkata:27": "both", "tool-hashkata:28": "both", "tool-hashkata:29": "src", "tool-hashkata:30": "src", "tool-hashkata:31": "both", "tool-hashkata:32": "both", "tool-hashkata:33": "both", "tool-hashkata:34": "both", "tool-hashkata:35": "both", "tool-hashkata:36": "both", "tool-hashkata:37": "src", "tool-hashkata:38": "src", "tool-hashkata:39": "src", "tool-hashkata:40": "src", "tool-hashkata:41": "all"};
