const FOOT_ELEM_NAME = {earth:'האדמה, העקב', water:'המים, הקשת', fire:'האש, הכריות', air:'האוויר, הבהונות'};
/* הפתולוגיות באתר שמתאימות לטקסט של המטופל */
function footPaths(text){
  const t = String(text||''), out = [];
  (typeof pathMatch==='function' ? pathMatch(t) : []).forEach(k=>{ const n = FOOT_PATH[k]; if(n && !out.includes(n)) out.push(n); });
  if(/אלרגי/.test(t) && !out.includes('אלרגיות')) out.push('אלרגיות');
  return out;
}
/* מעגלי הזמנים: גיל, ליסוד ולחלק שלו בכף הרגל.
   תקופת הגדילה: אדמה מלידה עד 3, מים עד 12.5, אש עד 20, אוויר עד 25. ומשם מחזורים של 25 שנה, באותו סדר. */
function footAgeZone(age){
  age = Number(age); if(!(age>=0) || age>120) return null;
  const cyc = Math.floor(age/25), a = age - cyc*25;
  const Z = [['earth',0,3],['water',3,12.5],['fire',12.5,20],['air',20,25]];
  const z = Z.find(x=>a>=x[1] && a<x[2]) || Z[3];
  const f = (a - z[1]) / (z[2]-z[1]);
  const part = f<1/3 ? 'בחלק התחתון' : f<2/3 ? 'באמצע' : 'בחלק העליון';
  return {key:z[0], name:FOOT_ELEM_NAME[z[0]], part, cycle:cyc};
}
/* גיל שבו התחיל משהו, מתוך טקסט חופשי: בגיל 30, לפני 3 שנים, לפני שנתיים, או שנה כמו 2019 */
function footAgesIn(text, nowAge){
  const t = String(text||''), out = [], now = Number(nowAge), Y = new Date().getFullYear();
  const W = {'שנה':1,'שנתיים':2,'שלוש':3,'ארבע':4,'חמש':5,'שש':6,'שבע':7,'שמונה':8,'תשע':9,'עשר':10};
  (t.match(/בגיל\s*(\d{1,2})/g)||[]).forEach(m=>out.push(+m.replace(/\D/g,'')));
  if(now>0){
    (t.match(/לפני\s*(\d{1,2})\s*שנים/g)||[]).forEach(m=>out.push(now - +m.replace(/\D/g,'')));
    (t.match(/לפני\s*(שנה|שנתיים|שלוש|ארבע|חמש|שש|שבע|שמונה|תשע|עשר)(?:\s*שנים)?/g)||[]).forEach(m=>{ const w = m.replace(/לפני\s*/,'').replace(/\s*שנים/,''); if(W[w]) out.push(now - W[w]); });
    (t.match(/(19|20)\d{2}/g)||[]).forEach(y=>{ const d = Y - +y; if(d>=0 && d<=now) out.push(now - d); });
  }
  return [...new Set(out.filter(a=>a>=0 && (!(now>0) || a<=now)))];
}

