const EX_LENS = [['moment','ברגע עצמו'],['daily','תרגול יומי'],['deep','עבודה מעמיקה']];
const EX_TAG_OVERRIDE = {};
const _exTagCache = {};
function exTags(id){
  if(_exTagCache[id]) return _exTagCache[id];
  const e = EXR[id]; if(!e) return {st:[], sit:[], len:''};
  const o = EX_TAG_OVERRIDE[id] || {};
  const head = `${e.title} ${e.why||''} ${e.fit||''}`, all = `${head} ${e.text}`;
  /* סגנון נחשב רק כשהוא עיקר התרגיל: מופיע בשם, או פעמיים לפחות בטקסט. משפט סיום כמו "כתבו שורה אחת" לא הופך תרגיל לתרגיל כתיבה */
  const hits = re => (e.text.match(new RegExp(re.source,'g'))||[]).length;
  let st = o.st || EX_STYLES.filter(([k,l,re])=>re.test(e.title) || hits(re)>=2).map(x=>x[0]);
  if(!st.length){ const body = e.text.slice(0, Math.ceil(e.text.length*0.7)); st = EX_STYLES.filter(([k,l,re])=>re.test(body)).map(x=>x[0]).slice(0,2); }
  if(!st.length) st = ['act']; /* תרגיל בלי סגנון מובהק הוא בדרך כלל מעשה קטן ביום יום */
  const sit = o.sit || EX_SITS.filter(([k,l,re])=>re.test(e.fit||e.why ? head : all)).map(x=>x[0]);
  const first = e.text.slice(0,140);
  const len = o.len || (/ברגע|לרגע|רגע של|כשעולה|כשמתחיל|לפני שעונים|בזמן ש/.test(e.title+' '+first) ? 'moment'
    : (e.text.length>900 || /שלב ראשון|\n.*\n.*\n/.test(e.text)) ? 'deep' : 'daily');
  return (_exTagCache[id] = {st, sit, len});
}
const EX_STYLE_NAME = Object.fromEntries(EX_STYLES.map(x=>[x[0],x[1]]));

/* ===================================================================
   יסודות וספירות: רובד מתוקן, ותצוגה בלי משבצות של רבדים (אוקטובר 2026)
   המזהה של תרגיל נשאר כמו שהוא, גם כשהרובד שלו מתוקן. הרובד משמש את ההצעות לתרגול:
   כשבשאלון מסומן איפה מורגש הלחץ, מוצע התרגיל מהרובד הזה.
   =================================================================== */
const EX_FLOOR_FIX = {
  'el:earth:ratzon:1':'guf',      /* למי שתקועים בנוקשות: מעשה שונה בכל יום */
  'el:water:machshava:2':'regesh',/* לשים לב לכן שרציתי שיהיה לא: דיבור */
  'el:fire:regesh:2':'machshava', /* שפלות רוח וענווה: התבוננות בערב */
  'sf:גבורה:machshava:1':'ratzon',/* לכבוש את היצר: דחף ורצון */
  'sf:תפארת:ratzon:1':'regesh',   /* אמת ורחמים יחד: שיחה */
  'sf:הוד:ratzon:1':'regesh',     /* להודות שאני לא יודע: דיבור */
  'sf:יסוד:machshava:0':'guf',    /* לסגור דבר פתוח: מעשה */
  'sf:כתר:regesh:0':'ratzon',     /* מה הניע אותי היום: מניעים */
  'sf:כתר:regesh:1':'ratzon',     /* מה מענג אותי באמת: תענוג */
  'sf:חכמה:ratzon:0':'machshava', /* יומן הברקות: רעיונות */
  'sf:דעת:ratzon:1':'guf'         /* להתחבר עד הסוף: מעשה עם כל החושים */
};
Object.entries(EX_FLOOR_FIX).forEach(([id,f])=>{ if(EXR[id]) EXR[id].floor = f; });
/* יסוד או ספירה: שלושה "להתחלה", אחד מהגוף, אחד מהרגש ואחד מהמחשבה, והשאר ב"עוד תרגילים", מסודרים לפי רובד */
(function(){
  const ORDER = ['guf','regesh','machshava','ratzon'];
  const _exLayout = exLayout;
  exLayout = function(src){
    if(!/^(el|sf):/.test(src)) return _exLayout(src);
    const xs = Object.values(EXR).filter(e=>e.src===src && !e.mine);
    if(!xs.length) return null;
    xs.sort((a,b)=>ORDER.indexOf(a.floor)-ORDER.indexOf(b.floor));
    const start = ['guf','regesh','machshava'].map(f=>xs.find(e=>e.floor===f)).filter(Boolean).map(e=>e.id);
    const rest = xs.map(e=>e.id).filter(id=>!start.includes(id));
    return [{label:'להתחלה', ids:start, start:true}, {label:'עוד תרגילים', ids:rest}];
  };
})();

